INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT134-S3-Q8$batch04$, 134, 3, 8, $batch04$Paradox$batch04$, $batch04$A recent study shows that those highways that carry the most traffic, and thus tend to be the most congested, have the lowest rate of fatal traffic accidents.$batch04$, $batch04$Which one of the following, if true, most helps to explain the phenomenon described above?$batch04$, $batch04$D$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=134 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT134-S3-Q8$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$Drivers have more accidents when they become distracted.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT134-S3-Q8$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$The highways that have the highest rate of fatal accidents have moderate volumes of traffic.$batch04$, $batch04$Restates Paradox$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT134-S3-Q8$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$Most of the motorists on very heavily traveled highways tend to be commuting to or from work.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT134-S3-Q8$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$Most serious accidents occur when vehicles are moving at a high rate of speed.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT134-S3-Q8$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$Heavily traveled highways do not always carry a higher proportion of large trucks.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT134-S3-Q8$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT134-S3-Q8$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$The highways with the most traffic tend to be the most congested.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$Those highways have the lowest rate of fatal accidents?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$You might expect more cars to mean more deadly crashes. But congestion also changes how people drive. If congestion keeps speeds low, and speed is what makes crashes deadly, the busiest roads could be the safest.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find something about congestion that makes fatal crashes less likely.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT134-S3-Q8$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Distraction causing accidents does not separate busy highways from quiet ones.$batch04$), ($batch04$B$batch04$, $batch04$This says where the high fatal rates are instead of explaining why the busiest roads have low ones.$batch04$), ($batch04$C$batch04$, $batch04$Knowing that the drivers are commuters does not tell us why they have fewer fatal accidents.$batch04$), ($batch04$D$batch04$, $batch04$Most serious accidents happen at high speed. Congested highways keep traffic slow, so they produce fewer of these deadly crashes.$batch04$), ($batch04$E$batch04$, $batch04$Busy highways "do not always" carry more trucks. This does not connect traffic to fatal accidents either way.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT134-S3-Q8$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
